import * as React from 'react'
import { PlasmicContactForm, DefaultContactFormProps } from './plasmic/hypernova_inc/PlasmicContactForm'
import { HTMLElementRefOf } from '@plasmicapp/react-web'
import { useRef, useState } from 'react'
import ContactFormErrorItem from './ContactFormErrorItem'
import { client } from '../src/utils/api-client'
import { createLead } from '../src/graphql/mutations'
import { toast, ToastContainer } from 'react-toastify'
import 'react-toastify/dist/ReactToastify.css'
import { env } from '../src/utils/env'
import {
  validateName,
  validateEmail,
  validatePhoneNumber,
  validateDescription,
  stripPromptInjectionTokens,
} from '../lib/contactValidation'
import { logger, describeError } from '../lib/logger'
import { HONEYPOT_FIELD, honeypotFieldProps } from '../lib/spamGuard'

// Your component props start with props for variants and slots you defined
// in Plasmic, but you can add more here, like event handlers that you can
// attach to named nodes in your component.
//
// If you don't want to expose certain variants or slots as a prop, you can use
// Omit to hide them:
//
// interface ContactFormProps extends Omit<DefaultContactFormProps, "hideProps1"|"hideProp2"> {
//   // etc.
// }
//
// You can also stop extending from DefaultContactFormProps altogether and have
// total control over the props for your component.
export interface ContactFormProps extends DefaultContactFormProps {
  style?: React.CSSProperties
}

/**
 * Reads the UTM/tracking context pages/_app.tsx stores in localStorage, so a
 * lead can be attributed to the campaign that produced it. Returns an empty
 * object when storage is unavailable (private mode, storage disabled) rather
 * than failing the submission -- attribution is nice to have, the lead is not.
 */
function readTrackingContext(): Record<string, string | undefined> {
  try {
    const raw = typeof window !== 'undefined' ? localStorage.getItem('hypernova_tracking') : null
    if (!raw) return {}
    const parsed = JSON.parse(raw)
    return {
      tracking_id_uuid: parsed.tracking_id || undefined,
      utm_source: parsed.utm_source || undefined,
      utm_medium: parsed.utm_medium || undefined,
      utm_campaign: parsed.utm_campaign || undefined,
      utm_content: parsed.utm_content || undefined,
      utm_term: parsed.utm_term || undefined,
    }
  } catch {
    return {}
  }
}

function ContactForm_(props: ContactFormProps, ref: HTMLElementRefOf<'form'>) {
  const [firstName, setFirstName] = useState('')
  const [lastName, setLastName] = useState('')
  const [email, setEmail] = useState('')
  const [number, setNumber] = useState('')
  const [description, setDescription] = useState('')

  // Error messages for each field
  const [errors, setErrors] = useState({
    firstName: '',
    lastName: '',
    email: '',
    number: '',
    description: '',
  })

  // Submission state
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Anti-spam signals. renderedAt is captured once on mount rather than at
  // submit time, so it measures how long the visitor actually had the form
  // open. useRef, not useState: changing it must never trigger a render.
  const renderedAt = useRef<number>(Date.now())
  const [honeypotValue, setHoneypotValue] = useState('')

  const handleFirstNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    // Strip unwanted characters in real-time (only allow letters and hyphens)
    const sanitized = validateName(e.target.value, 'First name').sanitized
    setFirstName(sanitized)
    // Clear error when user starts typing
    if (errors.firstName) {
      setErrors((prev) => ({ ...prev, firstName: '' }))
    }
  }
  const handleLastNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    // Strip unwanted characters in real-time (only allow letters and hyphens)
    const sanitized = validateName(e.target.value, 'Last name').sanitized
    setLastName(sanitized)
    if (errors.lastName) {
      setErrors((prev) => ({ ...prev, lastName: '' }))
    }
  }
  const handleEmailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    // Strip dangerous characters but allow email-valid characters
    const sanitized = e.target.value
      .replace(/[<>]/g, '') // Remove angle brackets
      .replace(/javascript:/gi, '') // Remove javascript protocol
      .replace(/on\w+=/gi, '') // Remove event handlers
    setEmail(sanitized)
    if (errors.email) {
      setErrors((prev) => ({ ...prev, email: '' }))
    }
  }
  const handleNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    // Allow only digits, spaces, dashes, parentheses, dots, and plus sign
    const sanitized = e.target.value.replace(/[^\d\s\-\(\)\.\+]/g, '')
    setNumber(sanitized)
    if (errors.number) {
      setErrors((prev) => ({ ...prev, number: '' }))
    }
  }
  const handleDescriptionChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    // Strip dangerous characters in real-time
    const sanitized = stripPromptInjectionTokens(
      e.target.value
        .replace(/[<>]/g, '')
        .replace(/javascript:/gi, '')
        .replace(/on\w+=/gi, '')
    )
    setDescription(sanitized)
    if (errors.description) {
      setErrors((prev) => ({ ...prev, description: '' }))
    }
  }

  // Blur handlers for real-time validation
  const handleFirstNameBlur = () => {
    const { errorMessage } = validateName(firstName, 'First name')
    setErrors((prev) => ({ ...prev, firstName: errorMessage }))
  }

  const handleLastNameBlur = () => {
    const { errorMessage } = validateName(lastName, 'Last name')
    setErrors((prev) => ({ ...prev, lastName: errorMessage }))
  }

  const handleEmailBlur = () => {
    const { errorMessage } = validateEmail(email)
    setErrors((prev) => ({ ...prev, email: errorMessage }))
  }

  const handleNumberBlur = () => {
    const { isValid, sanitized, errorMessage } = validatePhoneNumber(number)
    if (isValid && sanitized !== number) {
      setNumber(sanitized) // Auto-format the phone number
    }
    setErrors((prev) => ({ ...prev, number: errorMessage }))
  }

  const handleDescriptionBlur = () => {
    const { errorMessage } = validateDescription(description)
    setErrors((prev) => ({ ...prev, description: errorMessage }))
  }

  const handleFormSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault() // Prevent default form submission

    logger.debug('[contact-form] submit requested')

    // Validate and sanitize all fields
    const firstNameValidation = validateName(firstName, 'First name')
    const lastNameValidation = validateName(lastName, 'Last name')
    const emailValidation = validateEmail(email)
    const numberValidation = validatePhoneNumber(number)
    const descriptionValidation = validateDescription(description)

    // Set error messages
    const newErrors = {
      firstName: firstNameValidation.errorMessage,
      lastName: lastNameValidation.errorMessage,
      email: emailValidation.errorMessage,
      number: numberValidation.errorMessage,
      description: descriptionValidation.errorMessage,
    }

    setErrors(newErrors)

    // Check if there are any errors (non-empty error messages)
    const hasErrors = Object.values(newErrors).some((error) => error !== '')

    if (hasErrors) {
      logger.debug('[contact-form] blocked by validation', Object.keys(newErrors).filter((k) => newErrors[k as keyof typeof newErrors]))
      return
    }

    // Update state with sanitized values
    const sanitizedData = {
      firstName: firstNameValidation.sanitized,
      lastName: lastNameValidation.sanitized,
      email: emailValidation.sanitized,
      number: numberValidation.sanitized,
      description: descriptionValidation.sanitized,
    }

    // Update state
    setFirstName(sanitizedData.firstName)
    setLastName(sanitizedData.lastName)
    setEmail(sanitizedData.email)
    setNumber(sanitizedData.number)
    setDescription(sanitizedData.description)

    // Form is valid, proceed with submission

    setIsSubmitting(true)
    try {
      // HubSpot is the system of record: this form previously wrote only to
      // DynamoDB, so leads from the site's main contact form never reached the
      // CRM and sales never saw them. The estimator's contact step has always
      // posted here; both paths now behave the same way.
      //
      // Keep the trailing slash. next.config.mjs sets trailingSlash: true, and
      // without it the POST is redirected and the body is dropped.
      const response = await fetch('/api/create-hubspot-lead/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          firstName: sanitizedData.firstName,
          lastName: sanitizedData.lastName,
          email: sanitizedData.email,
          phoneNumber: sanitizedData.number,
          message: sanitizedData.description || undefined,
          environment: env,
          source: 'contact_form',
          renderedAt: renderedAt.current,
          [HONEYPOT_FIELD]: honeypotValue,
          ...readTrackingContext(),
        }),
      })

      const result = await response.json().catch(() => ({}))

      if (!response.ok) {
        // 429 deserves its own message: "try again" is actionable, whereas the
        // generic failure text invites the visitor to retry immediately and be
        // rejected again.
        throw new Error(
          response.status === 429
            ? 'Too many submissions from this network. Please try again in a few minutes.'
            : result.error || 'Failed to submit your information'
        )
      }

      // Secondary copy in DynamoDB. Best-effort by design: HubSpot has already
      // accepted the lead, so failing the visitor's submission over a
      // duplicate record would be the wrong trade.
      try {
        await client.graphql({
          query: createLead,
          variables: {
            input: {
              email: sanitizedData.email,
              firstName: sanitizedData.firstName,
              lastName: sanitizedData.lastName,
              phoneNumber: sanitizedData.number,
              description: sanitizedData.description || undefined,
              environment: env,
            },
          },
        })
      } catch (dbError) {
        logger.warn('[contact-form] secondary lead write failed', describeError(dbError))
      }

      window.dataLayer?.push({
        event: 'contact_form_submitted',
        env,
        app_env: env,
        source: 'contact_form',
      })

      logger.debug('[contact-form] lead created')

      // Show success toast
      toast.success("Thank you! Your information has been submitted successfully. We'll be in touch soon.", {
        position: 'bottom-right',
        autoClose: 5000,
        hideProgressBar: false,
        closeOnClick: true,
        pauseOnHover: true,
        draggable: true,
        theme: 'dark',
      })

      // Reset form after successful submission
      setFirstName('')
      setLastName('')
      setEmail('')
      setNumber('')
      setDescription('')
      setErrors({
        firstName: '',
        lastName: '',
        email: '',
        number: '',
        description: '',
      })
    } catch (error) {
      // Log the shape of the failure, never the payload -- the payload is
      // the visitor's personal data.
      logger.error('[contact-form] lead submission failed', describeError(error))
      toast.error(error instanceof Error ? error.message : 'There was an error submitting your information.', {
        position: 'bottom-right',
        autoClose: 5000,
        hideProgressBar: false,
        closeOnClick: true,
        pauseOnHover: true,
        draggable: true,
        theme: 'dark',
      })
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <>
      <PlasmicContactForm
        contactForm={{ ref, onSubmit: handleFormSubmit }}
        {...props}
        firstName={{
          value: firstName,
          onChange: handleFirstNameChange,
          onBlur: handleFirstNameBlur,
          hasError: !!errors.firstName,
        }}
        lastName={{
          value: lastName,
          onChange: handleLastNameChange,
          onBlur: handleLastNameBlur,
          hasError: !!errors.lastName,
        }}
        email={{
          value: email,
          onChange: handleEmailChange,
          onBlur: handleEmailBlur,
          hasError: !!errors.email,
        }}
        number={{
          value: number,
          onChange: handleNumberChange,
          onBlur: handleNumberBlur,
          hasError: !!errors.number,
        }}
        description={{
          value: description,
          onChange: handleDescriptionChange,
          onBlur: handleDescriptionBlur,
          hasError: !!errors.description,
        }}
        submitButton={{
          disabled:
            isSubmitting ||
            Object.values(errors).some((error) => error !== '') ||
            !firstName ||
            !lastName ||
            !email ||
            !number,
        }}
        hasError={Object.values(errors).some((error) => error !== '')}
        errors={{
          children: (
            <>
              {Object.entries(errors)
                .filter(([, errorMessage]) => errorMessage !== '')
                .map(([key, errorMessage]) => (
                  <ContactFormErrorItem key={key} errorMessage={errorMessage} />
                ))}
              {isSubmitting && <div style={{ marginTop: '10px', fontStyle: 'italic' }}>Submitting...</div>}
              {/*
                Honeypot. Invisible to humans, absent from the tab order and
                hidden from screen readers -- a trap that catches assistive
                technology users is not a trap, it is a bug that only affects
                disabled people. Rendered through an existing slot so this
                needs no Plasmic design change.
              */}
              <input
                {...honeypotFieldProps}
                value={honeypotValue}
                onChange={(e) => setHoneypotValue(e.target.value)}
              />
            </>
          ),
        }}
      />
      <ToastContainer />
    </>
  )
}

const ContactForm = React.forwardRef(ContactForm_)
export default ContactForm
